    "html": "<div class=\"atlas-appContainer\">\r\n      <div class=\"atlas-pageHeader\">\r\n        <div class=\"atlas-pageTitleGroup\">\r\n          <span class=\"atlas-pageEyebrow\">Preferências</span>\r\n          <h1 class=\"atlas-pageTitle\">Configurações</h1>\r\n          <p class=\"atlas-pageSubtitle\">Aparência, identidade e recursos experimentais desta sessão.</p>\r\n        </div>\r\n        <div class=\"atlas-pageActions\"><span class=\"atlas-badgeTag atlas-badgeInfo\">dev</span></div>\r\n      </div>\r\n      <section class=\"atlas-tableContainerCard\">\r\n        <div class=\"atlas-sectionCardHeader\"><div class=\"atlas-tabs\" role=\"tablist\"><button type=\"button\" class=\"atlas-tabBtn atlas-tabBtnActive\" data-atlas-tabs=\"settings\" data-atlas-tab=\"appearance\" aria-selected=\"true\">Aparência</button><button type=\"button\" class=\"atlas-tabBtn\" data-atlas-tabs=\"settings\" data-atlas-tab=\"identity\" aria-selected=\"false\">Identidade</button><button type=\"button\" class=\"atlas-tabBtn\" data-atlas-tabs=\"settings\" data-atlas-tab=\"flags\" aria-selected=\"false\">Feature flags</button></div></div>\r\n        <div data-atlas-tabs=\"settings\" data-atlas-panel=\"appearance\"><div class=\"atlas-optionCards\"><button type=\"button\" class=\"atlas-modalActionOption atlas-modalActionOptionChecked\" style=\"min-width:180px\" data-atlas-set-theme=\"dark\" aria-pressed=\"true\"><span class=\"atlas-root\" data-theme=\"dark\" style=\"background:none;width:auto\" aria-hidden=\"true\"><span class=\"atlas-themeSwatch\"><span></span><span></span></span></span><div><div class=\"atlas-modalActionLabel\">Atlas escuro</div><div class=\"atlas-settingDesc\">Superfícies escuras</div></div><span class=\"atlas-optionCheckCircle\"><span class=\"atlas-whenOn\">✓</span></span></button><button type=\"button\" class=\"atlas-modalActionOption\" style=\"min-width:180px\" data-atlas-set-theme=\"light\" aria-pressed=\"false\"><span class=\"atlas-root\" data-theme=\"light\" style=\"background:none;width:auto\" aria-hidden=\"true\"><span class=\"atlas-themeSwatch\"><span></span><span></span></span></span><div><div class=\"atlas-modalActionLabel\">Atlas claro</div><div class=\"atlas-settingDesc\">Cinza médio, menos brilho</div></div><span class=\"atlas-optionCheckCircle\"><span class=\"atlas-whenOn\">✓</span></span></button></div><div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Posição do menu</span><span class=\"atlas-settingDesc\">No topo (padrão) ou na lateral. Em telas estreitas (abaixo de 900px) o menu volta para o topo.</span></div><span></span></div><div class=\"atlas-optionCards\"><button type=\"button\" class=\"atlas-modalActionOption\" style=\"min-width:200px\" data-atlas-pref=\"nav:top\" data-atlas-pref-default aria-pressed=\"false\"><span aria-hidden=\"true\"><svg width=\"40\" height=\"28\" viewBox=\"0 0 40 28\" aria-hidden=\"true\"><rect x=\"1\" y=\"1\" width=\"38\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"currentColor\" opacity=\".5\"/><rect x=\"4\" y=\"4\" width=\"32\" height=\"5\" rx=\"2.5\" fill=\"currentColor\"/></svg></span><div><div class=\"atlas-modalActionLabel\">No topo</div><div class=\"atlas-settingDesc\">Pílulas ao lado da logo</div></div><span class=\"atlas-optionCheckCircle\"><span class=\"atlas-whenOn\">✓</span></span></button><button type=\"button\" class=\"atlas-modalActionOption\" style=\"min-width:200px\" data-atlas-pref=\"nav:side\" aria-pressed=\"false\"><span aria-hidden=\"true\"><svg width=\"40\" height=\"28\" viewBox=\"0 0 40 28\" aria-hidden=\"true\"><rect x=\"1\" y=\"1\" width=\"38\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"currentColor\" opacity=\".5\"/><rect x=\"4\" y=\"4\" width=\"9\" height=\"20\" rx=\"3\" fill=\"currentColor\"/></svg></span><div><div class=\"atlas-modalActionLabel\">Na lateral</div><div class=\"atlas-settingDesc\">Lista à esquerda, sempre visível</div></div><span class=\"atlas-optionCheckCircle\"><span class=\"atlas-whenOn\">✓</span></span></button></div><div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Área interna do Atlas</span><span class=\"atlas-settingDesc\">Mostra o catálogo e os recursos que o próprio time do Atlas usa, numa aba à parte no Catálogo e no Mapa de provisionamento. Desligado, essa aba não aparece.</span></div><button type=\"button\" class=\"atlas-switch\" data-atlas-pref-switch=\"internal\" aria-pressed=\"false\" aria-label=\"Mostrar a área interna do Atlas\"><span class=\"atlas-switchKnob\"></span></button></div></div><div data-atlas-tabs=\"settings\" data-atlas-panel=\"identity\" hidden><div class=\"atlas-profileRow\"><span class=\"atlas-avatar\">VC</span><div style=\"flex:1;min-width:0\"><div class=\"atlas-settingName\">Você (exemplo)</div><div class=\"atlas-settingDesc\">voce@empresa.com.br</div></div><button type=\"button\" class=\"atlas-btnPill\" data-atlas-signout>Sair</button></div>\r\n<div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Usuário</span><span class=\"atlas-settingDesc\">Como o portal identifica você. É esta referência que o RBAC usa para encontrar suas permissões.</span></div><span class=\"atlas-costMono\">user:default/voce</span></div>\r\n<div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Nome de exibição</span><span class=\"atlas-settingDesc\">Vem do perfil do provedor de login.</span></div><span class=\"atlas-costMono\">Você</span></div>\r\n<div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Grupos</span><span class=\"atlas-settingDesc\">Os grupos do catálogo aos quais você pertence. Sem grupo, o RBAC cai no padrão fechado.</span></div><a class=\"atlas-costMono\" style=\"color:inherit\" href=\"/my-groups\">group:default/plataforma</a></div>\r\n<div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Versão do portal</span><span class=\"atlas-settingDesc\">Identidade desta instalação, lida do app-config.</span></div><span class=\"atlas-costMono\">1.0.0 · dev</span></div></div><div data-atlas-tabs=\"settings\" data-atlas-panel=\"flags\" hidden><div class=\"atlas-settingRow\"><div class=\"atlas-settingInfo\"><span class=\"atlas-settingName\">Nenhuma feature flag registrada</span><span class=\"atlas-settingDesc\">Plugins registram flags para liberar funcionalidade em construção. Nenhum plugin instalado registrou uma.</span></div><span></span></div></div>\r\n      </section>\r\n    </div>",
